CREATE OR REPLACE FUNCTION public.set_variant_watch_baseline()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.watch_baseline IS NULL OR NEW.watch_baseline = 0 THEN
    NEW.watch_baseline := public.variant_watch_baseline(NEW.id);
  END IF;
  RETURN NEW;
END;
$function$
